// Ids: slides "s_" + 6 base36 chars, elements "e_" + 6, groups "g_" + 6 (docs/architecture.md, "Ids").
// Generated by whoever creates them, with crypto randomness (available in browsers and Node).

const BASE36 = "0123456789abcdefghijklmnopqrstuvwxyz";

function random36(n: number): string {
  const bytes = new Uint8Array(n);
  globalThis.crypto.getRandomValues(bytes);
  let out = "";
  // 252 = 36 * 7: reject higher bytes so every character is equally likely.
  for (let i = 0; i < n; i++) {
    let b = bytes[i]!;
    while (b >= 252) {
      const one = new Uint8Array(1);
      globalThis.crypto.getRandomValues(one);
      b = one[0]!;
    }
    out += BASE36[b % 36];
  }
  return out;
}

export function newSlideId(): string {
  return "s_" + random36(6);
}

export function newElementId(): string {
  return "e_" + random36(6);
}

/** Group ids are not specified by the architecture beyond "string"; we use the same shape as other ids. */
export function newGroupId(): string {
  return "g_" + random36(6);
}

export const SLIDE_ID_RE = /^s_[0-9a-z]{6}$/;
export const ELEMENT_ID_RE = /^e_[0-9a-z]{6}$/;

/** A fresh id that is not in `taken`. */
export function uniqueId(make: () => string, taken: { has(id: string): boolean }): string {
  for (;;) {
    const id = make();
    if (!taken.has(id)) return id;
  }
}
